sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // MSSRBXCE-610,613

    var payload = JSON.parse(current.getValue('iaw_widget_payload').toString());
    var mismatchedAttributes = [];
    var counterPartyValues = [];
    var brokerValues = [];
    //var counterPartyCommissions = '';
    var commissionStatus = 'false';

    for (var i = 0; i < payload.length; i++) {
        var item = payload[i];
        mismatchedAttributes.push(item.MISMATCHED_ATTRIBUTE);

        //counter_party_value
        var cptyValue = convertToFloat(item.MISMATCHED_DATA.CTAC_CTM_CPTY_VALUE);
        counterPartyValues.push(item.MISMATCHED_ATTRIBUTE + " " + cptyValue);
        //counterPartyValues.push(cptyValue);

        //CTAC_CTM_BROKER_VALUE
        var brkerValue = convertToFloat(item.MISMATCHED_DATA.CTAC_CTM_BROKER_VALUE);
        brokerValues.push(item.MISMATCHED_ATTRIBUTE + " " + brkerValue);
        //brokerValues.push(brkerValue);
        if (item.MISMATCHED_ATTRIBUTE.indexOf ('Commissions') != -1 ) {
            commissionStatus = 'true';
            grossConsideration = handleDecimal(current.financial_object.u_ctac_trade_audit_0_gross_consideration_f64);
            //cptyCommission = ((cptyValue / grossConsideration) * 10000).toString() || "";
            cptyCommission = ((cptyValue / grossConsideration) * 10000).toFixed(2).toString() || "";

        }
        //var grossConsideration = handleDecimal(current.financial_object.u_ctac_trade_audit_0_gross_consideration_f64);
        //var cptyCommission = ((cptyValue / grossConsideration) * 10000).toString() || "";


    }

    gs.info('mismatch: ' + mismatchedAttributes);

    if (mismatchedAttributes.length > 1) {
        current.setValue('mismatched_attribute', "Multiple");
        current.setValue('counter_party_value', counterPartyValues.join(' | \n'));
        current.setValue('ctac_ctm_broker_value', brokerValues.join(' | \n'));
    } else {
        current.setValue('mismatched_attribute', mismatchedAttributes.toString());
        current.setValue('counter_party_value', counterPartyValues.toString().substring(counterPartyValues.toString().indexOf(' ') + 1));
        current.setValue('ctac_ctm_broker_value', brokerValues.toString().substring(brokerValues.toString().indexOf(' ') + 1));
    }

    if (commissionStatus == 'true') {
        current.setValue('counter_party_commission', cptyCommission);
        current.setValue('commission_hsbc_bps', current.financial_object.u_basis_point);
    } else {
        current.setValue('counter_party_commission', '');
        current.setValue('commission_hsbc_bps', '');
    }

    current.update();

    function handleDecimal(str) {
        if (str.includes("E")) {
            var parts = str.split("E");
            var base = parts[0];
            var exponent = parts[1];
            var numericBase = parseFloat(base);
            var numericExponent = parseInt(exponent);
            var result = numericBase * Math.pow(10, numericExponent);
            return result;
        } else {
            return parseFloat(str);
        }
    }

    function convertToFloat(str) {
        var match = str.match(/(\d+,\d+)/);
		var value;
        if (match) {
            // replace comma
            var numStr = match[1].replace(',', '.');
            // convert to float
            value = parseFloat(numStr);
            //gs.info(value);
            return value;
        } else {
			value = str;
			return value;
            //gs.info('Failed to convert to float value!');
        }
    }

})(current, previous);
